window.LIB_LAZY=window.LIB_LAZY||{};
window.LIB_LAZY["eusebiu-istoria#218"]=[{"v":1,"t":"După ce am descris în șapte cărți întâmplările de la vremea apostolilor, socotim potrivit ca în această a opta carte să consemnăm, spre știința urmașilor, câteva dintre cele mai însemnate întâmplări ale vremii noastre, vrednice de a fi păstrate pentru totdeauna. Relatarea noastră va începe de aici."}];
window.LIB_LAZY["eusebiu-istoria#219"]=[{"v":1,"t":"Este peste puterea noastră să descriem în chip potrivit întinderea și felul slavei și libertății cu care cuvântul cucerniciei față de Dumnezeul universului, vestit lumii prin Hristos, era cinstit între toți oamenii, atât greci, cât și barbari, înainte de prigoana din zilele noastre."},{"v":2,"t":"Ca dovadă s-ar putea aduce bunăvoința arătată poporului nostru de către stăpânitori; căci le încredințau cârmuirea provinciilor și, din pricina marii prietenii pe care o aveau față de învățătura lor, îi scuteau de grija jertfirii."},{"v":3,"t":"De ce să mai vorbesc de cei din palatele împărătești și de stăpânitorii peste toți, care îngăduiau membrilor casei lor, soțiilor, copiilor și slujitorilor, să vorbească deschis înaintea lor despre cuvântul și viața dumnezeiască și îi lăsau aproape să se laude cu libertatea credinței lor?"},{"v":4,"t":"Într-adevăr, îi prețuiau mult și îi preferau tovarășilor lor de slujbă. Așa era acel Doroteu, cel mai devotat și mai credincios lor dintre toți și din această pricină deosebit de cinstit de ei între cei care țineau cele mai onorabile slujbe și cârmuiri. Cu el era vestitul Gorgoniu și toți câți fuseseră găsiți vrednici de aceeași distincție din pricina cuvântului lui Dumnezeu."},{"v":5,"t":"Și puteai vedea pe conducătorii din fiecare biserică primind cea mai mare bunăvoință de la toți ofițerii și guvernatorii. Dar cum ar putea cineva descrie acele adunări uriașe și mulțimea care se înghesuia în fiecare cetate și vestitele adunări din casele de rugăciune; din pricina cărora, nemulțumindu-se cu clădirile vechi, au ridicat din temelie biserici mari în toate cetățile?"},{"v":6,"t":"Nicio invidie nu a stat în calea înaintării acestor lucruri, care înaintau treptat și creșteau și sporeau zi de zi. Nici vreun demon rău nu le putea calomnia sau stânjeni prin sfaturi omenești, atâta vreme cât mâna dumnezeiască și cerească își veghea și își păzea poporul ca vrednic."},{"v":7,"t":"Dar când, din pricina libertății îmbelșugate, am căzut în moleșeală și lene și ne-am invidiat și ocărât unii pe alții și aproape, ca să zic așa, ne-am înarmat unii împotriva altora, conducători atacând pe conducători cu cuvinte ca niște sulițe și popor făcând partide împotriva poporului, și o făcătorie și prefăcătorie monstruoasă ridicându-se la culmea răutății, judecata dumnezeiască, cu îngăduință, cum îi place, pe când mulțimile încă mai continuau să se adune, a încercat blând și cumpătat episcopatul."},{"v":8,"t":"Această prigoană a început cu frații din armată. Dar ca și cum am fi fost fără simțire, nu ne grăbeam să facem Dumnezeirea binevoitoare și îndurătoare; și unii, ca niște atei, socoteau că treburile noastre sunt nebăgate în seamă și necârmuite; și astfel adăugam o răutate la alta. Și cei socotiți păstorii noștri, lepădând legătura cucerniciei, erau stârniți la lupte unii cu alții și nu făceau altceva decât să îngrămădească certuri și amenințări și gelozie și dușmănie și ură unii față de alții, ca niște tirani străduindu-se cu râvnă să-și afirme puterea. Atunci, într-adevăr, după cuvântul lui Ieremia: «Domnul în mânia Sa a întunecat fiica Sionului și a aruncat slava lui Israel din cer pe pământ și nu și-a adus aminte de așternutul picioarelor Sale în ziua mâniei Sale. Domnul a nimicit toate lucrurile frumoase ale lui Israel și a răsturnat toate întăriturile lui.» (Plângeri 2:1-2)"},{"v":9,"t":"Și după cum s-a prevestit în Psalmi: «A desființat legământul robului Său și a spurcat sfântul Său locaș la pământ — în nimicirea bisericilor — și a răsturnat toate întăriturile lui și a făcut din cetățuile lui lașitate. Toți cei ce trec au jefuit mulțimea poporului; și a ajuns încă o ocară pentru vecinii săi. Căci a înălțat dreapta dușmanilor săi și a întors ajutorul sabiei lui și nu l-a sprijinit în război. Ci l-a lipsit de curățire și a aruncat tronul lui la pământ. A scurtat zilele timpului său și, pe deasupra, a vărsat rușine peste el.»"}];
window.LIB_LAZY["eusebiu-istoria#220"]=[{"v":1,"t":"Toate acestea s-au împlinit în noi, când am văzut cu ochii noștri casele de rugăciune dărâmate până la temelii și dumnezeieștile și sfintele Scripturi date focului în mijlocul piețelor și păstorii bisericilor ascunși fără cinste pe ici pe colo, iar unii dintre ei prinși cu rușine și batjocoriți de dușmanii lor. Când s-a petrecut și, după un alt cuvânt proorocesc: «Disprețul a fost vărsat peste stăpânitori și i-a făcut să rătăcească pe o cale nebătută și fără drum.»"},{"v":2,"t":"Dar nu este locul nostru să descriem nenorocirile triste care au venit în cele din urmă peste ei, cum nu socotim potrivit nici să consemnăm dezbinările lor și purtarea nefirească unii față de alții înainte de prigoană. De aceea am hotărât să nu povestim nimic despre ei, în afară de lucrurile în care putem îndreptăți judecata dumnezeiască."},{"v":3,"t":"De aceea nu vom pomeni pe cei care au fost zdruncinați de prigoană, nici pe cei care în tot ce ține de mântuire au făcut naufragiu și de bunăvoia lor s-au scufundat în adâncul potopului. Ci vom introduce în această istorie, în general, doar acele întâmplări care pot fi de folos întâi nouă și apoi urmașilor. Să trecem, deci, să descriem pe scurt luptele sfinte ale martorilor Cuvântului dumnezeiesc."},{"v":4,"t":"Era în al nouăsprezecelea an al domniei lui Dioclețian, în luna Distru, numită de romani martie, când sărbătoarea patimii Mântuitorului era aproape, că s-au publicat pretutindeni edicte împărătești, poruncind ca bisericile să fie rase de pe fața pământului și Scripturile să fie nimicite prin foc și rânduind ca cei care aveau locuri de cinste să fie degradați și ca slujitorii casei, dacă stăruiau în mărturisirea creștinismului, să fie lipsiți de libertate."},{"v":5,"t":"Acesta a fost primul edict împotriva noastră. Dar nu mult după aceea s-au dat alte decrete, poruncind ca toți conducătorii bisericilor din fiecare loc să fie aruncați întâi în temniță și apoi, prin orice meșteșug, siliți să jertfească."}];
window.LIB_LAZY["eusebiu-istoria#221"]=[{"v":1,"t":"Atunci, într-adevăr, foarte mulți conducători ai bisericilor au îndurat cu râvnă suferințe cumplite și au dat pilde de lupte nobile. Dar o mulțime de alții, amorțiți la suflet de frică, au slăbit ușor la prima năvală. Dintre ceilalți, fiecare a îndurat alte feluri de chin. Trupul unuia a fost biciuit cu nuiele. Altul a fost pedepsit cu chinuri de neîndurat de întindere și răzuire, în care unii au suferit o moarte ticăloasă."},{"v":2,"t":"Alții au trecut prin alte lupte. Astfel unul, în timp ce cei din jur îl împingeau cu de-a sila și îl târau la jertfele scârboase și necurate, a fost lăsat să plece ca și cum ar fi jertfit, deși nu jertfise. Altul, deși nu se apropiase deloc și nu atinsese nimic spurcat, când alții au spus că a jertfit, a plecat, purtând învinuirea în tăcere."},{"v":3,"t":"Altul, fiind ridicat pe jumătate mort, a fost lăsat deoparte ca și cum ar fi fost deja mort, și iarăși un anume om, zăcând pe pământ, a fost târât departe de picioare și numărat printre cei care jertfiseră. Unul a strigat și cu glas tare și-a mărturisit lepădarea jertfei; altul a strigat că este creștin, strălucind în mărturisirea Numelui mântuitor. Altul a declarat că nu a jertfit și nu va jertfi niciodată."},{"v":4,"t":"Dar au fost loviți peste gură și făcuți să tacă de o ceată mare de soldați așezată în acest scop; și au fost loviți peste față și obraji și alungați cu de-a sila; atât de important socoteau dușmanii cucerniciei să pară, prin orice mijloc, că și-au atins scopul. Dar aceste lucruri nu le-au folosit împotriva sfinților martiri; pentru a căror descriere exactă, ce cuvânt al nostru ar putea fi de ajuns?"}];
window.LIB_LAZY["eusebiu-istoria#222"]=[{"v":1,"t":"Căci am putea povesti despre mulți care au arătat o râvnă minunată pentru religia Dumnezeului universului, nu numai de la începutul prigoanei generale, ci cu mult înainte de acel timp, pe când încă domnea pacea."},{"v":2,"t":"Căci deși cel care primise puterea părea acum trezit ca dintr-un somn adânc, totuși din vremea de după Deciu și Valerian uneltise pe ascuns și fără vestire împotriva bisericilor. Nu ne-a făcut război tuturor deodată, ci a încercat la început doar pe cei din armată. Căci socotea că ceilalți pot fi luați lesne dacă îi va ataca și îi va supune mai întâi pe aceștia. Atunci mulți dintre soldați au fost văzuți îmbrățișând cu cea mai mare voioșie viața privată, ca să nu tăgăduiască cucernicia lor față de Făcătorul universului."},{"v":3,"t":"Căci atunci când comandantul, oricine a fost, a început să-i prigonească pe soldați, despărțindu-i pe triburi și curățind pe cei înscriși în armată, dându-le alegerea fie să primească, ascultând, onoarea care li se cuvenea, fie, dimpotrivă, să fie lipsiți de ea dacă nu ascultă porunca, o mulțime de soldați ai împărăției lui Hristos au preferat, fără șovăire, îndată, mărturisirea Lui în locul slavei aparente și al prosperității de care se bucurau."},{"v":4,"t":"Și unul și altul dintre ei au primit uneori în schimb, pentru statornicia lor cucernică, nu numai pierderea poziției, ci moartea. Dar deocamdată instigatorul acestei uneltiri a procedat cu moderație și s-a aventurat până la sânge doar în unele cazuri; căci mulțimea credincioșilor, cum e firesc, l-a înspăimântat și l-a oprit să ducă război deodată împotriva tuturor."},{"v":5,"t":"Dar când a făcut atacul mai cu îndrăzneală, este cu neputință de povestit câți și ce fel de martiri ai lui Dumnezeu se puteau vedea, printre locuitorii tuturor cetăților și țărilor."}];
window.LIB_LAZY["eusebiu-istoria#223"]=[{"v":1,"t":"Îndată după publicarea decretului împotriva bisericilor din Nicomedia, un anume om, nu necunoscut, ci foarte mult cinstit cu înalte demnități lumești, mișcat de râvnă pentru Dumnezeu și stârnit de credință aprinsă, a apucat edictul pe când era afișat deschis și public și l-a rupt în bucăți ca pe un lucru profan și nelegiuit; și aceasta s-a făcut pe când doi dintre stăpânitori erau în aceeași cetate — cel mai vârstnic dintre toți și cel care ținea locul al patrulea în cârmuire după el."},{"v":2,"t":"Dar acest om, cel dintâi în acel loc, după ce s-a distins astfel, a suferit cele ce urmau firesc unei asemenea îndrăzneli și și-a ținut duhul voios și netulburat până la moarte."}];
window.LIB_LAZY["eusebiu-istoria#224"]=[{"v":1,"t":"Această vreme a dat martiri dumnezeiești și strălucitori, mai presus de toți cei ale căror laude s-au cântat vreodată și care au fost sărbătoriți pentru curaj, fie între greci, fie între barbari, în persoana lui Doroteu și a slujitorilor care erau cu el în palat. Deși primiseră cele mai înalte onoruri de la stăpânii lor și erau tratați de ei ca propriii lor copii, au socotit ocările și încercările pentru religie și multele feluri de moarte născocite împotriva lor drept, în adevăr, bogății mai mari decât slava și desfătarea acestei vieți."},{"v":2,"t":"Vom descrie felul în care unul dintre ei și-a sfârșit viața și vom lăsa cititorii să deducă din cazul lui suferințele celorlalți. Un anume om a fost adus în cetatea pomenită înaintea stăpânitorilor despre care am vorbit. I s-a poruncit atunci să jertfească, dar fiindcă a refuzat, s-a poruncit să fie dezbrăcat și ridicat în sus și bătut cu nuiele pe tot trupul, până când, fiind biruit, avea să facă, chiar împotriva voinței lui, ce i se poruncea."},{"v":3,"t":"Dar cum rămânea nemișcat de aceste suferințe și oasele îi apăreau deja, au amestecat oțet cu sare și l-au turnat pe părțile sfâșiate ale trupului. Cum disprețuia aceste chinuri, au adus un grătar și foc. Și rămășițele trupului lui, ca o carne menită mâncării, au fost puse pe foc, nu deodată, ca să nu piară pe loc, ci puțin câte puțin. Și celor care l-au pus pe rug nu li s-a îngăduit să înceteze până nu va încuviința, după asemenea suferințe, cele poruncite."},{"v":4,"t":"Dar el și-a ținut cu tărie hotărârea și, biruitor, și-a dat viața în timp ce chinurile încă mergeau. Astfel a fost martiriul unuia dintre slujitorii palatului, care era într-adevăr foarte vrednic de numele lui, căci se numea Petru."},{"v":5,"t":"Martiriul celorlalți, deși nu era mai prejos decât al lui, îl vom trece cu vederea pentru scurtime, consemnând doar că Doroteu și Gorgoniu, cu mulți alții din casa împărătească, după felurite suferințe, și-au încheiat viețile prin sugrumare și au purtat trofeele biruinței date de Dumnezeu."},{"v":6,"t":"În acest timp Antim, care păstorea atunci biserica din Nicomedia, a fost decapitat pentru mărturia lui despre Hristos. O mare mulțime de martiri i s-a adăugat, un incendiu izbucnind în acele zile în palatul din Nicomedia, nu știu cum, care printr-o falsă bănuială a fost pus în seama poporului nostru. Familii întregi de oameni cucernici de acolo au fost omorâte în masă la porunca împărătească, unii prin sabie, alții prin foc. Se povestește că, cu o anumită râvnă dumnezeiască și de nedescris, bărbați și femei s-au repezit în foc. Și călăii au legat un mare număr de alții și i-au pus pe bărci și i-au aruncat în adâncul mării."},{"v":7,"t":"Iar cei care fuseseră socotiți stăpânii lor au considerat necesar să dezgroape trupurile slujitorilor împărătești, care fuseseră date pământului cu o îngropare cuvenită, și să le arunce în mare, ca nu cumva cineva, socotindu-i zei, cum credeau ei, să li se închine în mormintele lor."},{"v":8,"t":"Astfel de lucruri s-au petrecut în Nicomedia la începutul prigoanei. Dar nu mult după aceea, când unii din țara numită Melitene și alții din toată Siria au încercat să uzurpe cârmuirea, un edict împărătesc a poruncit ca păstorii bisericilor de pretutindeni să fie aruncați în temniță și lanțuri."},{"v":9,"t":"Ce se putea vedea după aceasta depășește orice descriere. O mulțime uriașă a fost întemnițată în fiecare loc; și închisorile de pretutindeni, care fuseseră pregătite de mult pentru ucigași și jefuitori de morminte, s-au umplut de episcopi, prezbiteri și diaconi, citeți și exorciști, așa încât nu mai rămăsese în ele loc pentru cei osândiți pentru crime."},{"v":10,"t":"Și cum alte decrete au urmat celui dintâi, poruncind ca cei din închisoare, dacă vor jertfi, să fie lăsați să plece în libertate, iar cei care refuză să fie chinuiți cu multe chinuri, cum ar putea cineva, iarăși, să numere mulțimea martirilor din fiecare provincie, și mai ales a celor din Africa, Mauritania, Tebaida și Egipt? Din această din urmă țară mulți au mers în alte cetăți și provincii și au devenit strălucitori prin martiriu."}];
window.LIB_LAZY["eusebiu-istoria#225"]=[{"v":1,"t":"Pe cei dintre ei care au fost însemnați în Palestina îi cunoaștem, ca și pe cei care au fost la Tir în Fenicia. Cine, văzându-i, nu s-a uimit de loviturile nenumărate și de tăria pe care au arătat-o sub ele acești atleți cu adevărat minunați ai religiei? Și de lupta lor, îndată după biciuire, cu fiare sălbatice însetate de sânge, când erau aruncați înaintea leoparzilor și a diferite feluri de urși și mistreți și tauri îndemnați cu foc și cu fier înroșit? Și de răbdarea minunată a acestor oameni nobili în fața tot felul de fiare sălbatice?"},{"v":2,"t":"Am fost de față noi înșine când s-au petrecut aceste lucruri și am consemnat puterea dumnezeiască a Mântuitorului nostru martirizat, Isus Hristos, care a fost de față și s-a arătat cu putere în martiri. Multă vreme fiarele mâncătoare de oameni nu au cutezat să atingă sau să se apropie de trupurile celor dragi lui Dumnezeu, ci se aruncau asupra celorlalți care, din afară, le iritau și le îndemnau. Și nu atingeau câtuși de puțin pe sfinții atleți, pe când aceștia stăteau singuri și goi și le făceau semne cu mâinile ca să le tragă spre ei — căci li se poruncise să facă aceasta. Dar de câte ori se năpusteau asupra lor, erau reținute ca printr-o putere dumnezeiască și se retrăgeau din nou."},{"v":3,"t":"Aceasta a continuat mult timp și a pricinuit uimire nu mică spectatorilor. Și cum prima fiară sălbatică nu făcea nimic, a doua și a treia au fost slobozite împotriva aceluiași martir."},{"v":4,"t":"Nu te puteai opri să nu fii uimit de tăria nebiruită a acestor oameni sfinți și de statornicia răbdătoare și neclintită a celor cu trupuri tinere. Puteai vedea un tânăr de nici douăzeci de ani stând nelegat și întinzându-și mâinile în chip de cruce, cu mintea neînfricată și netremurândă, ocupat cu râvnă în rugăciune către Dumnezeu și nemișcându-se câtuși de puțin înapoi sau retrăgându-se din locul în care stătea, în timp ce urși și leoparzi, suflând furie și moarte, aproape îi atingeau carnea. Și totuși gurile lor erau reținute, nu știu cum, de o putere dumnezeiască și de neînțeles și alergau înapoi la locul lor. Așa era el."},{"v":5,"t":"Iarăși puteai vedea pe alții, căci erau cinci în total, aruncați înaintea unui taur sălbatic, care arunca în aer cu coarnele pe cei care se apropiau din afară și îi sfâșia, lăsându-i să fie ridicați pe jumătate morți; dar când se năpustea cu furie și amenințare asupra sfinților martiri, care stăteau singuri, nu putea să se apropie de ei; ci deși bătea din picioare și împungea în toate părțile cu coarnele și sufla furie și amenințare din pricina iritării fierelor arzătoare, era totuși ținut înapoi de sfânta Purtare de grijă. Și cum nu le făcea niciun rău, au slobozit asupra lor alte fiare sălbatice."},{"v":6,"t":"În cele din urmă, după aceste atacuri cumplite și felurite asupra lor, au fost toți uciși cu sabia; și în loc să fie îngropați în pământ, au fost dați valurilor mării."}];
window.LIB_LAZY["eusebiu-istoria#226"]=[{"v":1,"t":"Aceasta a fost lupta acelor egipteni care au luptat nobil pentru religie în Tir. Dar trebuie să admirăm și pe cei care au suferit martiriul în țara lor; unde mii de bărbați, femei și copii, disprețuind viața de acum pentru învățătura Mântuitorului nostru, au îndurat felurite morți."},{"v":2,"t":"Unii dintre ei, după răzuiri și întinderi și cele mai aspre biciuiri și nenumărate alte feluri de chinuri, cumplite chiar de auzit, au fost dați flăcărilor; unii au fost înecați în mare; unii și-au oferit cu vitejie capetele celor care le tăiau; unii au murit sub chinuri, iar alții au pierit de foame. Și încă alții au fost răstigniți; unii după metoda folosită de obicei pentru răufăcători; alții și mai cumplit, fiind pironiți pe cruce cu capul în jos și ținuți în viață până au pierit pe cruce de foame."}];
window.LIB_LAZY["eusebiu-istoria#227"]=[{"v":1,"t":"Ar fi cu neputință să descriem ultragiile și chinurile pe care le-au îndurat martirii din Tebaida. Au fost răzuiți pe tot trupul cu scoici în loc de cârlige până au murit. Femeile erau legate de un picior și ridicate în aer cu mașini și, cu trupurile cu totul goale și neacoperite, înfățișau tuturor privitorilor acest spectacol cel mai rușinos, crud și neomenos."},{"v":2,"t":"Alții, legați de ramurile și trunchiurile copacilor, pieriră. Căci trăgeau laolaltă, cu mașini, cele mai groase ramuri și legau de ele mădularele martirilor; și apoi, lăsând ramurile să-și reia poziția firească, sfâșiau îndată mădularele celor pentru care născociseră aceasta."},{"v":3,"t":"Toate acestea s-au făcut nu câteva zile sau un timp scurt, ci timp de o lungă serie de ani. Uneori mai mult de zece, alteori peste douăzeci erau omorâți. Iarăși, nu mai puțin de treizeci, apoi cam șaizeci și încă o dată o sută de bărbați, cu copii mici și femei, erau uciși într-o singură zi, fiind osândiți la felurite și diverse chinuri."},{"v":4,"t":"Noi înșine, aflându-ne pe loc, am văzut mulțimi mari într-o singură zi; unii suferind decapitarea, alții chinul prin foc; așa încât sabia ucigătoare s-a tocit și, slăbind, s-a rupt, și chiar călăii au obosit și s-au schimbat unii pe alții."},{"v":5,"t":"Și am văzut cea mai minunată râvnă și energia și osârdia cu adevărat dumnezeiască a celor care credeau în Hristosul lui Dumnezeu. Căci de îndată ce sentința a fost rostită împotriva celui dintâi, unul după altul se repezeau la scaunul de judecată și se mărturiseau creștini. Și privind cu nepăsare lucrurile cumplite și chinurile multiforme, se declarau cu îndrăzneală și neînfricare pentru religia Dumnezeului universului. Și primeau sentința finală de moarte cu bucurie și râs și voioșie; așa încât cântau și înălțau imnuri și mulțumiri Dumnezeului universului până la ultima suflare."},{"v":6,"t":"Aceștia erau, într-adevăr, minunați; dar și mai minunați erau cei care, deosebindu-se prin avere, neam ales și onoare și prin învățătură și filozofie, socoteau totul secundar față de adevărata religie și credința în Mântuitorul și Domnul nostru Isus Hristos."},{"v":7,"t":"Așa era Filoromus, care ținea o slujbă înaltă în guvernarea imperială la Alexandria și care făcea dreptate în fiecare zi, însoțit de o gardă militară potrivită rangului și demnității lui romane. Așa era și Fileas, episcopul bisericii din Tmuis, un om însemnat prin patriotismul lui și serviciile aduse țării sale și prin învățătura lui filozofică."},{"v":8,"t":"Acești oameni, deși o mulțime de rude și alți prieteni îi rugau, și mulți din poziții înalte, ba chiar judecătorul însuși îi implora să aibă milă de ei înșiși și să se îndure de copiii și soțiile lor, totuși nu au fost câtuși de puțin îndemnați de acestea să aleagă dragostea de viață și să disprețuiască rânduielile Mântuitorului nostru privind mărturisirea și tăgăduirea. Ci cu minți bărbătești și filozofice, sau mai bine zis cu suflete cucernice și iubitoare de Dumnezeu, au stăruit împotriva tuturor amenințărilor și insultelor judecătorului; și amândoi au fost decapitați."}];
window.LIB_LAZY["eusebiu-istoria#228"]=[{"v":1,"t":"Fiindcă l-am pomenit pe Fileas ca având o înaltă reputație în învățătura lumească, să fie el însuși martor în următorul extras, în care ne arată cine era și, totodată, descrie mai exact decât putem noi martiriile petrecute în vremea lui la Alexandria:"},{"v":2,"t":"Având înaintea lor toate aceste pilde și modele și semne nobile care ne sunt date în dumnezeieștile și sfintele Scripturi, fericiții martiri care erau cu noi nu au șovăit, ci îndreptând ochiul sufletului cu sinceritate spre Dumnezeul de peste toate și având mintea pusă pe moarte pentru religie, s-au ținut cu tărie de chemarea lor. Căci înțelegeau că Domnul nostru Isus Hristos s-a făcut om pentru noi, ca să taie tot păcatul și să ne dea mijlocul de intrare în viața veșnică. Căci «n-a socotit o pradă a fi deopotrivă cu Dumnezeu, ci S-a golit pe Sine, luând chip de rob; și găsindu-Se în înfățișare ca un om, S-a smerit până la moarte, și încă moarte de cruce.» (Filipeni 2:6-8)"},{"v":3,"t":"De aceea, fiind râvnitori pentru darurile cele mai mari, martirii purtători de Hristos au îndurat toate încercările și toate felurile de născociri de chin; nu o singură dată, ci unii și a doua oară. Și deși paznicii se întreceau unii cu alții în a-i amenința în tot felul, nu numai în cuvinte, ci și în fapte, nu și-au părăsit hotărârea; pentru că «dragostea desăvârșită alungă frica.» (1 Ioan 4:18)"},{"v":4,"t":"Ce cuvinte ar putea descrie curajul și bărbăția lor în orice chin? Căci fiindu-le dată libertatea de a-i maltrata tuturor celor care voiau, unii îi băteau cu ciomege, alții cu nuiele, alții cu bice, încă alții cu curele, iar alții cu funii."},{"v":5,"t":"Și spectacolul ultragiilor era variat și arăta mare răutate. Căci unii, cu mâinile legate la spate, erau atârnați în butuci și fiecare mădular le era întins cu anumite mașini. Apoi chinuitorii, după cum li se poruncise, le sfâșiau cu unelte tot trupul; nu numai coastele, ca în cazul ucigașilor, ci și stomacul, genunchii și obrajii. Alții erau ridicați în sus, atârnați de portic de o mână, și îndurau cea mai cumplită suferință dintre toate, prin întinderea încheieturilor și mădularelor. Alții erau legați față în față de stâlpi, nesprijinindu-se pe picioare, ci cu greutatea trupurilor apăsând pe legături și strângându-le tare."},{"v":6,"t":"Și îndurau aceasta nu doar cât timp guvernatorul vorbea cu ei sau era liber, ci aproape toată ziua. Căci atunci când trecea la alții, lăsa ofițeri din subordinea lui să-i păzească pe cei dintâi și să observe dacă vreunul, biruit de chinuri, părea că cedează. Și poruncea să-i arunce în lanțuri fără milă și apoi, când erau la ultima suflare, să-i arunce la pământ și să-i târască."},{"v":7,"t":"Căci spunea că nu trebuie să aibă nici cea mai mică grijă de noi, ci să gândească și să acționeze ca și cum nu am mai fi, dușmanii noștri născocind acest al doilea fel de chin pe lângă lovituri."},{"v":8,"t":"Unii, de asemenea, după aceste ultragii, erau puși în butuci și li se întindeau ambele picioare peste patru găuri, așa încât erau siliți să zacă pe spate în butuci, neputându-se ține sus din pricina rănilor proaspete cu care le era acoperit tot trupul în urma biciuirii. Alții erau aruncați la pământ și zăceau acolo sub suma chinurilor, arătând privitorilor o manifestare și mai cumplită a asprimii, purtând pe trupuri semnele pedepselor felurite și diverse care fuseseră născocite."},{"v":9,"t":"Pe măsură ce aceasta continua, unii mureau sub chinuri, făcând de rușine pe potrivnic prin statornicia lor. Alții, pe jumătate morți, erau închiși în temniță și, suferind în chinurile lor, mureau în câteva zile; dar ceilalți, însănătoșindu-se sub îngrijirea primită, căpătau încredere cu timpul și prin lunga lor reținere în închisoare."},{"v":10,"t":"Când li s-a poruncit, deci, să aleagă dacă vor fi eliberați de supărare atingând jertfa spurcată și vor primi de la ei blestemata libertate, sau, refuzând să jertfească, vor fi condamnați la moarte, nu au șovăit, ci au mers la moarte voioși. Căci știau ce fusese declarat mai înainte de sfintele Scripturi. Căci se spune: «Cel ce jertfește altor zei va fi nimicit cu desăvârșire» (Exod 22:20) și: «Să nu ai alți dumnezei afară de Mine.» (Exod 20:3)"},{"v":11,"t":"Astfel sunt cuvintele martirului cu adevărat filozof și iubitor de Dumnezeu, pe care, înainte de sentința finală, pe când era încă în închisoare, le-a adresat frațiilor din parohia lui, arătându-le împrejurările sale și totodată îndemnându-i să se țină, chiar și după moartea lui apropiată, de religia lui Hristos."},{"v":12,"t":"Dar de ce să stăruim asupra acestor lucruri și să continuăm a adăuga noi pilde ale luptelor martirilor dumnezeiești de pe tot pământul, mai ales că nu mai erau tratați după legea obișnuită, ci atacați ca dușmani de război?"}];
window.LIB_LAZY["eusebiu-istoria#229"]=[{"v":1,"t":"Un orășel din Frigia, locuit numai de creștini, a fost înconjurat de soldați pe când bărbații erau în el. Aruncând foc în el, i-au mistuit împreună cu femeile și copiii pe când chemau pe Hristos. Aceasta au făcut-o pentru că toți locuitorii cetății, și curatorul însuși, și guvernatorul, cu toți cei care aveau slujbe, și tot poporul s-au mărturisit creștini și nu au ascultat câtuși de puțin pe cei care le porunceau să se închine idolilor."},{"v":2,"t":"A mai fost un alt om de demnitate romană numit Adauct, dintr-o familie nobilă italiană, care înaintase prin toate onorurile sub împărați, așa încât ocupase fără vină chiar slujbele generale de magistrat, cum le numesc ei, și de ministru de finanțe. Pe lângă toate acestea excela în fapte de cucernicie și în mărturisirea Hristosului lui Dumnezeu și a fost împodobit cu diadema martiriului. A îndurat lupta pentru religie pe când încă ținea slujba de ministru de finanțe."}];
window.LIB_LAZY["eusebiu-istoria#230"]=[{"v":1,"t":"De ce să-i mai pomenim pe ceilalți pe nume sau să numărăm mulțimea bărbaților sau să zugrăvim felurile de suferințe ale minunaților martiri ai lui Hristos? Unii dintre ei au fost uciși cu securea, ca în Arabia. Mădularele unora au fost zdrobite, ca în Capadocia. Unii, ridicați în sus de picioare, cu capul în jos, în timp ce un foc ușor ardea dedesubt, au fost sufocați de fumul ridicat din lemnul care ardea, cum s-a făcut în Mesopotamia. Alții au fost schilodiți prin tăierea nasului, a urechilor și a mâinilor și prin tăierea în bucăți a celorlalte mădulare și părți ale trupului, ca în Alexandria."},{"v":2,"t":"De ce să înviem amintirea celor din Antiohia care au fost fripți pe grătare, nu ca să fie omorâți, ci ca să fie supuși unei pedepse îndelungate? Sau a altora care au preferat să-și bage mâna dreaptă în foc decât să atingă jertfa nelegiuită? Unii, temându-se de încercare, în loc să fie prinși și să cadă în mâinile dușmanilor lor, s-au aruncat de pe case înalte, socotind moartea preferabilă cruzimii celor nelegiuiți."},{"v":3,"t":"O anumită persoană sfântă — în suflet admirabilă prin virtute, în trup femeie — care era strălucită mai presus de toți în Antiohia prin avere, neam și reputație, își crescuse în principiile religiei cele două fiice, aflate atunci în prospețimea și floarea vieții. Fiindcă se stârnise mare invidie din pricina lor, s-au folosit toate mijloacele ca să fie găsite în ascunzătoarea lor; și când s-a aflat că sunt plecate, au fost chemate prin înșelăciune la Antiohia. Astfel au fost prinse în mrejele soldaților. Când femeia s-a văzut pe sine și pe fiicele ei astfel neajutorate și a știut lucrurile cumplite de spus pe care le-ar face bărbații cu ele — și cel mai de nesuferit dintre toate lucrurile cumplite, amenințata siluire a castității lor — s-a îndemnat pe sine și pe fecioare că nu trebuie să se supună nici măcar să audă de aceasta. Căci, a zis ea, a-și preda sufletele robiei demonilor este mai rău decât toate morțile și pieirile; și le-a pus înainte singura izbăvire de toate acestea — scăparea la Hristos."},{"v":4,"t":"Ele au ascultat atunci sfatul ei. Și după ce și-au aranjat veșmintele cuviincios, s-au abătut din mijlocul drumului, cerând paznicilor puțin timp de retragere, și s-au aruncat într-un râu care curgea pe acolo."},{"v":5,"t":"Astfel s-au nimicit pe ele însele. Dar mai erau alte două fecioare în aceeași cetate a Antiohiei, care slujeau lui Dumnezeu în toate și erau surori adevărate, strălucite prin neam și deosebite prin viață, tinere și înflorite, serioase la minte, cucernice în purtare și admirabile prin râvnă. Ca și cum pământul nu ar fi putut suporta o asemenea desăvârșire, închinătorii demonilor au poruncit să fie aruncate în mare. Și aceasta li s-a făcut."},{"v":6,"t":"În Pont, alții au îndurat suferințe oribile de auzit. Degetele le erau străpunse cu trestii ascuțite pe sub unghii. Plumb topit, clocotind și fierbând de căldură, a fost turnat pe spatele altora și au fost fripți în cele mai sensibile părți ale trupului."},{"v":7,"t":"Alții au îndurat în măruntaie și în părțile ascunse chinuri rușinoase, neomenoase și de nepomenit, pe care judecătorii nobili și păzitori ai legii, ca să-și arate asprimea, le-au născocit ca manifestări mai onorabile ale înțelepciunii. Și noi chinuri se născoceau necontenit, ca și cum se străduiau, întrecându-se unii pe alții, să câștige premii într-o întrecere."},{"v":8,"t":"Dar la încheierea acestor nenorociri, când nu mai puteau născoci cruzimi mai mari și erau obosiți de omoruri și sătui și îmbuibați de vărsarea de sânge, s-au întors la ceea ce socoteau tratament milos și omenos, așa încât păreau că nu mai născocesc lucruri cumplite împotriva noastră."},{"v":9,"t":"Căci spuneau că nu se cuvine ca cetățile să fie spurcate cu sângele propriului lor popor sau ca cârmuirea stăpânitorilor lor, care era bună și blândă față de toți, să fie defăimată prin cruzime excesivă; ci că mai degrabă binefacerea autorității omenoase și împărătești să se întindă asupra tuturor și să nu mai fim omorâți. Căci aplicarea acestei pedepse asupra noastră trebuia oprită ca urmare a omeniei stăpânitorilor."},{"v":10,"t":"De aceea s-a poruncit să ni se scoată ochii și să fim schilodiți la unul dintre mădulare. Căci asemenea lucruri erau omenoase în ochii lor și cea mai ușoară dintre pedepsele pentru noi. Așa încât acum, din pricina acestei purtări binevoitoare arătate nouă de cei nelegiuiți, era cu neputință de spus numărul nesocotit al celor cărora li se scosese întâi ochiul drept cu sabia și apoi fusese cauterizat cu foc; sau care fuseseră schilodiți la piciorul stâng prin arderea încheieturilor și apoi osândiți la minele de aramă ale provinciei, nu atât pentru slujbă, cât pentru chin și greutate. Pe lângă toate acestea, alții au întâmpinat alte încercări, imposibil de povestit; căci răbdarea lor bărbătească întrece orice descriere."},{"v":11,"t":"În aceste lupte, nobilii martiri ai lui Hristos au strălucit pe tot pământul și pretutindeni i-au uimit pe cei care le priveau bărbăția; și dovezile puterii cu adevărat dumnezeiești și de nespus a Mântuitorului nostru s-au arătat prin ei. A-i numi pe fiecare pe nume ar fi o sarcină lungă, dacă nu chiar cu neputință."}];
window.LIB_LAZY["eusebiu-istoria#231"]=[{"v":1,"t":"Cât despre conducătorii Bisericii care au suferit martiriul în cetățile principale, primul martir al împărăției lui Hristos pe care îl vom pomeni printre monumentele celor cucernici este Antim, episcopul cetății Nicomedia, care a fost decapitat."},{"v":2,"t":"Printre martirii din Antiohia a fost Lucian, un prezbiter al acelei parohii, a cărui viață întreagă a fost din cele mai alese. La Nicomedia, în prezența împăratului, a vestit împărăția cerească a lui Hristos, întâi într-o apărare orală și apoi și prin fapte."},{"v":3,"t":"Dintre martirii din Fenicia, cei mai deosebiți au fost acei păstori devotați ai turmelor duhovnicești ale lui Hristos: Tirannion, episcopul bisericii din Tir; Zenobiu, prezbiter al bisericii din Sidon; și Silvan, episcopul bisericilor din jurul Emesei."},{"v":4,"t":"Ultimul dintre aceștia, cu alții, a fost făcut hrană fiarelor sălbatice la Emesa și a fost astfel primit în rândurile martirilor. Ceilalți doi au slăvit cuvântul lui Dumnezeu la Antiohia prin răbdare până la moarte. Episcopul a fost aruncat în adâncul mării. Dar Zenobiu, care era un medic foarte iscusit, a murit din pricina unor chinuri grele aplicate pe coaste."},{"v":5,"t":"Dintre martirii din Palestina, Silvan, episcopul bisericilor din jurul Gazei, a fost decapitat împreună cu alți treizeci și nouă la minele de aramă din Feno. Tot acolo episcopii egipteni Peleu și Nil, cu alții, au suferit moartea prin foc."},{"v":6,"t":"Printre aceștia trebuie să-l pomenim pe Pamfil, un prezbiter, care a fost marea slavă a parohiei din Cezareea și între oamenii vremii noastre cel mai admirabil."},{"v":7,"t":"Virtutea faptelor lui bărbătești am consemnat-o la locul potrivit. Dintre cei care au suferit moartea în chip strălucit la Alexandria și în tot Egiptul și Tebaida, trebuie pomenit mai întâi Petru, episcopul Alexandriei, unul dintre cei mai aleși învățători ai religiei lui Hristos; iar dintre prezbiterii împreună cu el, Faust, Diu și Ammoniu, martiri desăvârșiți ai lui Hristos; de asemenea Fileas, Hesihiu, Pahimiu și Teodor, episcopi ai bisericilor egiptene, și pe lângă ei mulți alți oameni deosebiți care sunt pomeniți de parohiile țării și ținutului lor. Nu ne revine nouă să descriem luptele celor care au suferit pentru religia dumnezeiască pe tot pământul și să povestim cu exactitate ce s-a întâmplat fiecăruia dintre ei. Aceasta ar fi lucrarea cuvenită celor care au fost martori oculari ai întâmplărilor. Pe cele pe care le-am văzut eu însumi le voi descrie pentru urmași într-o altă lucrare."},{"v":8,"t":"Dar în cartea de față voi adăuga la cele date revocarea emisă de persecutorii noștri și întâmplările petrecute la începutul prigoanei, care vor fi cele mai folositoare celor care le vor citi."},{"v":9,"t":"Ce cuvinte ar putea înfățișa îndeajuns măreția și belșugul prosperității guvernării romane înainte de războiul împotriva noastră, cât timp stăpânitorii erau prietenoși și pașnici față de noi? Atunci cei care erau în vârful cârmuirii și ținuseră poziția zece sau douăzeci de ani își petreceau timpul în pace liniștită, în sărbători și jocuri publice și cele mai voioase plăceri și veselie."},{"v":10,"t":"Pe când autoritatea lor creștea astfel fără întrerupere și sporea zi de zi, deodată și-au schimbat atitudinea pașnică față de noi și au început un război neîmpăcat. Dar al doilea an al acestei mișcări nu trecuse încă, când s-a petrecut o revoluție în toată cârmuirea și a răsturnat toate lucrurile."},{"v":11,"t":"Căci o boală grea a venit peste căpetenia celor despre care am vorbit, prin care i s-a tulburat mintea; și el, împreună cu cel cinstit cu al doilea rang, s-a retras în viața privată. Abia făcuse aceasta, când tot imperiul s-a împărțit; lucru despre care nu se înregistrează că s-ar fi petrecut vreodată mai înainte."},{"v":12,"t":"Nu mult după aceea, împăratul Constanțiu, care toată viața fusese cel mai bun și bine-voitor față de supușii săi și cel mai prietenos Cuvântului dumnezeiesc, și-a încheiat viața în cursul obișnuit al firii și l-a lăsat pe propriul său fiu, Constantin, împărat și Augustus în locul lui. El a fost cel dintâi pus de ei între zei și a primit după moarte toate onorurile pe care le poate da cineva unui împărat."},{"v":13,"t":"A fost cel mai bun și mai blând dintre împărați și singurul dintre cei din zilele noastre care și-a petrecut tot timpul cârmuirii într-un chip vrednic de slujba lui. Mai mult, s-a purtat față de toți în chipul cel mai binevoitor și binefăcător. Nu a luat nici cea mai mică parte la războiul împotriva noastră, ci a păstrat pe cei cucernici care erau sub el nevătămați și nemaltratați. Nici nu a dărâmat clădirile bisericilor, nici nu a născocit altceva împotriva noastră. Sfârșitul vieții lui a fost cinstit și întreit fericit. Singur la moarte și-a lăsat imperiul în chip fericit și slăvit propriului său fiu ca urmaș — unul care era în toate privințele foarte chibzuit și cucernic."},{"v":14,"t":"Fiul său Constantin a luat îndată cârmuirea, fiind proclamat împărat suprem și Augustus de soldați și, cu mult înainte, de Dumnezeu însuși, Împăratul tuturor. S-a arătat un râvnitor al cucerniciei tatălui său față de învățătura noastră. Așa era el. Dar după aceasta, Licinius a fost declarat împărat și Augustus prin votul comun al stăpânitorilor."},{"v":15,"t":"Acestea l-au întristat mult pe Maximin, căci până atunci fusese numit de toți doar Cezar. El, fiind peste măsură poruncitor, și-a însușit demnitatea și a devenit Augustus, făcut astfel de el însuși. Între timp, cel despre care am pomenit că și-a reluat demnitatea după abdicare, fiind descoperit că uneltea împotriva vieții lui Constantin, a pierit printr-o moarte foarte rușinoasă. A fost cel dintâi ale cărui decrete și statui și monumente publice au fost distruse din pricina răutății și nelegiuirii lui."}];
window.LIB_LAZY["eusebiu-istoria#232"]=[{"v":1,"t":"Maxențiu, fiul lui, care a obținut cârmuirea la Roma, a prefăcut la început credința noastră, din complezență și lingușire față de poporul roman. Din această pricină a poruncit supușilor săi să înceteze prigonirea creștinilor, prefăcându-se religios ca să pară milos și blând mai mult decât predecesorii săi."},{"v":2,"t":"Dar nu s-a dovedit în fapte a fi omul care se spera, ci a alergat în toată răutatea și nu s-a ferit de nicio necurăție sau destrăbălare, săvârșind adultere și dedându-se la tot felul de corupție. Căci despărțind soțiile de soții lor legitimi, le-a ultragiat și le-a trimis înapoi la bărbații lor în chipul cel mai necinstit. Și nu a practicat aceasta numai împotriva celor obscuri și necunoscuți, ci i-a insultat mai ales pe cei mai de seamă și mai deosebiți membri ai senatului roman."},{"v":3,"t":"Toți supușii lui, popor și conducători, cinstiți și obscuri, erau istoviți de grea asuprire. Nici, deși stăteau liniștiți și îndurau amara robie, nu era vreo ușurare de cruzimea ucigătoare a tiranului. Odată, sub un pretext mărunt, a dat poporul să fie măcelărit de gărzile lui; și o mare mulțime din poporul roman a fost omorâtă în mijlocul cetății, cu sulițele și armele nu ale sciților și barbarilor, ci ale propriilor lor concetățeni."},{"v":4,"t":"Ar fi cu neputință să se povestească numărul senatorilor omorâți pentru averea lor; mulțimi fiind ucise sub felurite pretexte."},{"v":5,"t":"Ca încununare a toată răutatea lui, tiranul a recurs la magie. Și în divinațiile lui tăia femei însărcinate și iarăși cerceta măruntaiele nou-născuților. Înjunghia lei și săvârșea diferite acte execrabile pentru a chema demoni și a îndepărta războiul. Căci singura lui nădejde era ca, prin aceste mijloace, să-i fie asigurată biruința."},{"v":6,"t":"Este cu neputință de spus în ce chipuri își asuprea tiranul de la Roma supușii, așa încât au fost reduși la o lipsă atât de extremă a celor necesare vieții cum nu s-a mai cunoscut vreodată, după spusele contemporanilor noștri, nici la Roma, nici în altă parte."},{"v":7,"t":"Dar Maximin, tiranul din Răsărit, formând pe ascuns o alianță prietenoasă cu tiranul roman ca și cu un frate în răutate, a căutat să o ascundă multă vreme. Dar fiind descoperit în cele din urmă, a suferit pedeapsa meritată."},{"v":8,"t":"Era minunat cât de înrudit era în răutate cu tiranul de la Roma, sau mai bine zis cât de mult îl întrecea în ea. Căci căpeteniile vrăjitorilor și magilor erau cinstite de el cu cel mai înalt rang. Devenind peste măsură de fricos și superstițios, prețuia mult rătăcirea idolilor și a demonilor. Într-adevăr, fără ghicitori și oracole nu cuteza să miște nici măcar un deget, ca să zic așa."},{"v":9,"t":"De aceea ne-a prigonit mai violent și mai necontenit decât predecesorii săi. A poruncit să se ridice temple în fiecare cetate și să fie refăcute repede crângurile sfinte care fuseseră nimicite prin trecerea timpului. A rânduit preoți idolești în fiecare loc și cetate; și a pus peste ei în fiecare provincie, ca mare preot, vreun dregător politic care se distinsese în mod deosebit în orice fel de slujbă, dându-i o ceată de soldați și o gardă de corp. Și tuturor scamatorilor, ca și cum ar fi fost cucernici și iubiți ai zeilor, le-a acordat guvernări și cele mai mari privilegii."},{"v":10,"t":"Din acel timp încolo a necăjit și a chinuit nu o cetate sau o țară, ci toate provinciile aflate sub autoritatea lui, prin extreme stoarceri de aur și argint și bunuri și cele mai grele urmăriri și diverse amenzi. A luat de la cei bogați averea pe care o moșteniseră de la strămoșii lor și a dat bogății uriașe și sume mari de bani lingușitorilor din jurul său."},{"v":11,"t":"Și a ajuns la un asemenea exces de nebunie și beție încât mintea lui era tulburată și rătăcită în petrecerile lui; și da porunci pe când era beat, de care se căia apoi când era treaz. Nu îngăduia nimănui să-l întreacă în destrăbălare și risipă, ci s-a făcut învățător al răutății pentru cei din jurul său, atât stăpânitori, cât și supuși. A îndemnat armata să trăiască desfrânat în orice fel de petreceri și neînfrânare și a încurajat pe guvernatori și generali să-și maltrateze supușii cu răpire și lăcomie, aproape ca și cum ar fi fost stăpânitori împreună cu el."},{"v":12,"t":"De ce să povestim faptele desfrânate, fără rușine, ale omului sau să numărăm mulțimea cu care a săvârșit adulter? Căci nu putea trece printr-o cetate fără să corupă neîncetat femei și să siluiască fecioare."},{"v":13,"t":"Și în aceasta a reușit cu toți, în afară de creștini. Căci disprețuind moartea, ei nu se sinchiseau de puterea lui. Căci bărbații au îndurat foc și sabie și răstignire și fiare sălbatice și adâncul mării și tăierea mădularelor și arderi și împungeri și scoaterea ochilor și schilodiri ale întregului trup și, pe lângă acestea, foamete și mine și lanțuri. În toate au arătat răbdare pentru religie, mai degrabă decât să treacă idolilor reverența datorată lui Dumnezeu."},{"v":14,"t":"Și femeile nu au fost mai puțin bărbătești decât bărbații pentru învățătura Cuvântului dumnezeiesc, îndurând lupte împreună cu bărbații și luând premii egale de virtute. Și când erau târâte spre scopuri stricate, și-au predat viețile morții mai degrabă decât trupurile necurăției."},{"v":15,"t":"Doar una dintre cele prinse de tiran pentru scopuri adultere, o creștină foarte deosebită și strălucită din Alexandria, a învins sufletul pătimaș și neînfrânat al lui Maximin printr-o fermitate cât se poate de eroică. Cinstită prin avere, neam și educație, le-a socotit pe toate acestea mai prejos de castitate. El a stăruit pe lângă ea de multe ori, dar deși ea era gata să moară, nu a putut-o omorî, căci dorința lui era mai tare decât mânia lui."},{"v":16,"t":"A pedepsit-o, deci, cu exil și i-a luat toată averea. Mulți alții, neputând nici măcar să asculte amenințările cu siluirea de la stăpânitorii păgâni, au îndurat orice fel de chinuri și întinderi și pedepse de moarte. Aceștia, într-adevăr, trebuie admirați. Dar de departe cea mai admirabilă a fost acea femeie din Roma, cu adevărat cea mai nobilă și mai smerită dintre toate, pe care tiranul Maxențiu, asemănându-se pe deplin cu Maximin în fapte, a încercat să o ultrajeze."},{"v":17,"t":"Căci când a aflat că cei care slujeau tiranul în asemenea treburi erau la casă (era și ea creștină) și că bărbatul ei, deși prefect al Romei, îi va lăsa să o ia și să o ducă, cerând puțin timp pentru a-și împodobi trupul, a intrat în odaia ei și, rămasă singură, s-a înjunghiat cu o sabie. Murind îndată, a lăsat trupul ei celor care veniseră după ea. Și prin faptele ei, mai puternic decât prin orice cuvinte, a arătat tuturor oamenilor, acum și de acum înainte, că virtutea care domnește între creștini este singura stăpânire nebiruită și nepieritoare."},{"v":18,"t":"Aceasta a fost calea răutății care a fost dusă înainte, în același timp, de cei doi tirani care stăpâneau Răsăritul și Apusul. Cine ar șovăi, după o cercetare atentă, să declare prigoana împotriva noastră pricina unor asemenea rele? Mai ales că această extremă încurcătură a treburilor nu a încetat până când creștinii nu au dobândit libertatea."}];
window.LIB_LAZY["eusebiu-istoria#233"]=[{"v":1,"t":"În tot timpul celor zece ani ai prigoanei, au uneltit și s-au războit necontenit unii împotriva altora. Căci marea nu putea fi navigată și oamenii nu puteau naviga din niciun port fără a fi expuși la tot felul de ultragii; fiind întinși pe roată și sfâșiați pe coaste, ca să se afle prin felurite chinuri dacă veneau de la dușman; și fiind în cele din urmă supuși pedepsei prin cruce sau prin foc."},{"v":2,"t":"Și pe lângă acestea se pregăteau scuturi și platoșe și se făceau gata sulițe și lănci și alte unelte de război, iar galere și armură navală se adunau în fiecare loc. Și nimeni nu aștepta altceva decât să fie atacat de dușmani în orice zi. Pe lângă aceasta, foamete și ciumă au venit peste ei, despre care vom povesti ce este necesar la locul potrivit."}];
window.LIB_LAZY["eusebiu-istoria#234"]=[{"v":1,"t":"Aceasta a fost starea treburilor în toată prigoana. Dar în al zecelea an, prin harul lui Dumnezeu, a încetat cu totul, începând să scadă după al optulea an. Căci atunci când harul dumnezeiesc și ceresc ne-a arătat o supraveghere binevoitoare și îndurătoare, atunci, într-adevăr, stăpânitorii noștri, chiar persoanele prin care fusese purtat cu râvnă războiul împotriva noastră, și-au schimbat în chip cât se poate de remarcabil mintea și au dat o revocare și au stins marele foc al prigoanei care fusese aprins, prin proclamații și rânduieli milostive privind pe noi."},{"v":2,"t":"Dar aceasta nu s-a datorat vreunei lucrări omenești; nici nu a fost rezultatul, cum s-ar putea spune, al milei sau filantropiei stăpânitorilor noștri — departe de aceasta, căci zilnic, de la început până în acel timp, născoceau măsuri tot mai aspre împotriva noastră și inventau necontenit ultragii printr-o mai mare varietate de unelte — ci s-a datorat în mod vădit supravegherii Purtării de grijă dumnezeiești, care, pe de o parte, se împăca cu poporul Său, iar pe de alta, îl ataca pe cel care instigase aceste rele și se arăta mâniată împotriva lui ca autor al cruzimilor întregii prigoane."},{"v":3,"t":"Căci deși era necesar ca aceste lucruri să se petreacă după judecata dumnezeiască, totuși Cuvântul spune: «Vai de cel prin care vine sminteala!» (Matei 18:7) De aceea pedeapsa de la Dumnezeu a venit peste el, începând cu trupul și mergând la suflet."},{"v":4,"t":"Căci un abces a apărut deodată în mijlocul părților ascunse ale trupului său și din el o rană adânc străpunsă, care s-a întins de neoprit în măruntaiele lui cele mai lăuntrice. Din ele a ieșit o mulțime de nespus de viermi și s-a ridicat un miros de moarte, căci întreaga masă a trupului lui se schimbase, prin lăcomia lui, înainte de boală, într-o grămadă excesivă de grăsime moale, care a putrezit și a înfățișat astfel o priveliște cumplită și de neîndurat celor care se apropiau."},{"v":5,"t":"Unii dintre medici, neputând îndura în niciun chip nespusa urâciune a mirosului, au fost omorâți; alții, cum întreaga masă se umflase și trecuse dincolo de nădejdea refacerii și nu puteau da niciun ajutor, au fost omorâți fără milă."}];
window.LIB_LAZY["eusebiu-istoria#235"]=[{"v":1,"t":"Luptându-se cu atâtea rele, s-a gândit la cruzimile pe care le săvârșise împotriva celor cucernici. Întorcându-și, deci, gândurile spre sine, a mărturisit întâi pe față Dumnezeului universului și apoi, chemându-și slujitorii, a poruncit ca fără zăbavă să oprească prigoana creștinilor și să-i îndemne, prin lege și decret împărătesc, să-și zidească bisericile și să-și îndeplinească slujba obișnuită, înălțând rugăciuni pentru împărat. Îndată fapta a urmat cuvântului."},{"v":2,"t":"Decretele imperiale au fost publicate în cetăți, cuprinzând revocarea faptelor împotriva noastră în următoarea formă:"},{"v":3,"t":"Împăratul Cezar Galeriu Valeriu Maximin, Nebiruitul, Augustul, Pontif Maxim, biruitor al germanilor, biruitor al egiptenilor, biruitor al tebanilor, de cinci ori biruitor al sarmaților, biruitor al perșilor, de două ori biruitor al carpilor, de șase ori biruitor al armenilor, biruitor al medilor, biruitor al adiabenilor, tribun al poporului pentru a douăzecea oară, împărat pentru a nouăsprezecea oară, consul pentru a opta oară, părinte al patriei, proconsul;"},{"v":4,"t":"și împăratul Cezar Flaviu Valeriu Constantin, Cucernicul, Fericitul, Nebiruitul, Augustul, Pontif Maxim, tribun al poporului, împărat pentru a cincea oară, consul, părinte al patriei, proconsul;"},{"v":5,"t":"și împăratul Cezar Valeriu Licinius, Cucernicul, Fericitul, Nebiruitul, Augustul, Pontif Maxim, tribun al poporului pentru a patra oară, împărat pentru a treia oară, consul, părinte al patriei, proconsul; poporului provinciilor lor, salutare:"},{"v":6,"t":"Printre celelalte lucruri pe care le-am rânduit spre folosul și câștigul public, am voit mai înainte să readucem totul în conformitate cu legile străvechi și disciplina publică a romanilor și să rânduim ca și creștinii, care au părăsit religia strămoșilor lor, să se întoarcă la o bună dispoziție."},{"v":7,"t":"Căci într-un fel oarecare, o asemenea trufie îi cuprinsese și o asemenea prostie îi ajunsese, încât nu urmau rânduielile străvechi pe care poate strămoșii lor înșiși le întemeiaseră mai înainte, ci își făceau legi după propriul lor scop, cum dorea fiecare, și le păzeau și astfel se adunau în congregații separate în diferite locuri."},{"v":8,"t":"Când am dat acest decret ca ei să se întoarcă la rânduielile întemeiate de cei vechi, foarte mulți s-au supus sub primejdie, dar foarte mulți, fiind prigoniți, au îndurat tot felul de morți."},{"v":9,"t":"Și fiindcă mulți continuă în aceeași nebunie și vedem că nici nu aduc zeilor cerești închinarea care li se cuvine, nici nu iau în seamă pe Dumnezeul creștinilor, în considerarea filantropiei noastre și a obiceiului nostru neschimbat, prin care suntem deprinși să acordăm iertare tuturor, am hotărât că trebuie să ne întindem cu cea mai mare bucurie îngăduința și în această chestiune; ca ei să fie iarăși creștini și să zidească din nou adunările în care erau deprinși să se adune, cu condiția ca ei să nu facă nimic împotriva disciplinei. Într-o altă scrisoare vom arăta magistraților ce au de păzit."},{"v":10,"t":"De aceea, în urma acestei îngăduințe a noastre, ei trebuie să-L implore pe Dumnezeul lor pentru siguranța noastră și a poporului și a lor înșiși, ca binele public să fie păstrat în fiecare loc și ei să trăiască în siguranță în casele lor."},{"v":11,"t":"Aceasta este cuprinsul acestui edict, tradus, pe cât s-a putut mai bine, din limba romană în greacă. Este timpul să luăm în considerare ce s-a petrecut după aceste întâmplări."}];
window.LIB_LAZY["eusebiu-istoria#236"]=[{"v":1,"t":"Autorul edictului, foarte curând după această mărturisire, a fost eliberat de dureri și a murit. Se spune că a fost autorul inițial al nenorocirii prigoanei, străduindu-se, cu mult înaintea mișcării celorlalți împărați, să abată de la credință pe creștinii din armată și mai întâi pe cei din propria lui casă, degradând pe unii din rangul militar și maltratând rușinos pe alții și amenințând încă pe alții cu moartea, și în cele din urmă îndemnându-și tovarășii la imperiu la prigoana generală. Nu se cuvine să trecem sub tăcere moartea acestor împărați."},{"v":2,"t":"Fiind patru care ținuseră autoritatea supremă, cei înaintați în vârstă și onoare, după ce prigoana continuase nu pe deplin doi ani, au abdicat de la cârmuire, după cum am spus deja, și și-au petrecut restul vieții într-o stare obișnuită și privată."},{"v":3,"t":"Sfârșitul vieții lor a fost următorul. Cel dintâi în onoare și vârstă a pierit printr-o lungă și foarte grea slăbiciune trupească. Cel care ținea locul al doilea și-a încheiat viața prin sugrumare, suferind astfel după o anumită prevestire demonică, din pricina multelor lui crime îndrăznețe."},{"v":4,"t":"Dintre cei de după ei, ultimul, despre care am vorbit ca inițiator al întregii prigoane, a suferit cele pe care le-am povestit. Dar cel dinaintea lui, prea milostivul și bunul împărat Constanțiu, și-a petrecut tot timpul cârmuirii într-un chip vrednic de slujba lui. Mai mult, s-a purtat față de toți în chipul cel mai binevoitor și binefăcător. Nu a luat nici cea mai mică parte la războiul împotriva noastră și a păstrat pe cei cucernici care erau sub el nevătămați și nemaltratați. Nici nu a dărâmat clădirile bisericilor, nici nu a născocit altceva împotriva noastră. Sfârșitul vieții lui a fost fericit și întreit binecuvântat. Singur la moarte și-a lăsat imperiul în chip fericit și slăvit propriului său fiu ca urmaș, unul care era în toate privințele foarte chibzuit și cucernic. A luat îndată cârmuirea, fiind proclamat împărat suprem și Augustus de soldați;"},{"v":5,"t":"și s-a arătat un râvnitor al cucerniciei tatălui său față de învățătura noastră. Astfel au fost morțile celor patru despre care am scris, petrecute în timpuri diferite."},{"v":6,"t":"Dintre aceștia, mai departe, doar cel pomenit de noi puțin mai sus, cu cei care au împărțit mai târziu cârmuirea, a publicat în cele din urmă pe față tuturor mărturisirea amintită, în edictul scris pe care l-a dat."}];
